		"column_more_than_row_fields",
		testConf, NewDefaultObservability(testConf))
	assert.Nil(t, e)
	assert.NotNil(t, r)

	r, e = NewRows(context.Background(), newMockAthenaClient(),
		"row_fields_more_than_column",
		testConf, NewDefaultObservability(testConf))
	assert.Nil(t, e)
	assert.NotNil(t, r)

	r, e = NewRows(context.Background(), newMockAthenaClient(),
		"GetQueryResultsWithContext_return_error",
		testConf, NewDefaultObservability(testConf))
	assert.NotNil(t, e)
	assert.Nil(t, r)

	// rawValue is nil
	r, e = NewRows(context.Background(), newMockAthenaClient(),
		"missing_data_resp",
		testConf, NewDefaultObservability(testConf))
	assert.Nil(t, e)
	assert.NotNil(t, r)
	var dest []driver.Value = make([]driver.Value, 8)
	e = r.Next(dest)
	assert.Equal(t, e, nil)

	// raise error for missing value
	testConf.SetMissingAsEmptyString(false)
	testConf.SetMissingAsDefault(false)
	r, e = NewRows(context.Background(), newMockAthenaClient(),
		"missing_data_resp",
		testConf, NewDefaultObservability(testConf))
	assert.Nil(t, e)
	assert.NotNil(t, r)
	e = r.Next(dest)
	assert.Equal(t, e.Error(), "Missing data at column c1")

	r, e = NewRows(context.Background(), newMockAthenaClient(),
		"missing_data_resp2",
		testConf, NewDefaultObservability(testConf))
	assert.Nil(t, e)
	assert.NotNil(t, r)
	e = r.Next(dest)
	assert.NotEqual(t, e, io.EOF)

	// error when row.Next()
	r, e = NewRows(context.Background(), newMockAthenaClient(),
		"SELECT_GetQueryResults_ERR",
		testConf, NewDefaultObservability(testConf))
	assert.Nil(t, e)
	assert.NotNil(t, r)
	for {
		e = r.Next(dest)
		if e != nil {
			assert.Equal(t, e, ErrTestMockGeneric)
			break
		}
	}

	// missing row in page
	r, e = NewRows(context.Background(), newMockAthenaClient(),
		"SELECT_EMPTY_ROW_IN_PAGE",
		testConf, NewDefaultObservability(testConf))
	assert.Nil(t, e)
	assert.NotNil(t, r)
	for {
		e = r.Next(dest)
		if e != nil {
			assert.Equal(t, e, io.EOF)
			break
		}
	}

	// close in the loop
	r, e = NewRows(context.Background(), newMockAthenaClient(),
		"SELECT_GetQueryResults_ERR",
		testConf, NewDefaultObservability(testConf))
	assert.Nil(t, e)
	assert.NotNil(t, r)
	cnt := 0
	for {
		e = r.Next(dest)
		if e != nil {
			assert.Equal(t, e, io.EOF)
			break
		}
		if cnt == 7 {
			r.Close()
		}
		cnt++
	}

}

